BEGIN
    -- Xóa các thuốc ATC demo đã import trước đó để reset về dữ liệu sạch.
    IF demo_table_exists('prescription_items') AND demo_column_exists('prescription_items', 'medication_id') AND demo_table_exists('medications') THEN
        IF demo_column_exists('medications','atc_code') THEN
            EXECUTE 'DELETE FROM prescription_items pi USING medications m WHERE pi.medication_id = m.id AND m.atc_code = ANY($1)' USING codes;
        ELSIF demo_column_exists('medications','code') THEN
            EXECUTE 'DELETE FROM prescription_items pi USING medications m WHERE pi.medication_id = m.id AND m.code = ANY($1)' USING codes;
        END IF;
    END IF;

    IF demo_table_exists('medications') THEN
        IF demo_column_exists('medications','atc_code') THEN
            EXECUTE 'DELETE FROM medications WHERE atc_code = ANY($1)' USING codes;
        ELSIF demo_column_exists('medications','code') THEN
            EXECUTE 'DELETE FROM medications WHERE code = ANY($1)' USING codes;
        END IF;
    END IF;
END $$;

